import {occupancy} from './utilities.js?v=geyser-park-1';
export const NEIGHBORHOOD_RADII=[2,4,8,16];
const fields=['policeCoverage','fireCoverage','healthCoverage','childEducationCoverage','collegeEducationCoverage','adultEducationCoverage','airPollution','waterPollution','crime','landValue'];
export function neighborhoodSnapshot(city,center,radius=4){
 if(!Number.isInteger(center?.x)||!Number.isInteger(center?.y)||center.x<0||center.y<0||center.x>=city.size||center.y>=city.size||!NEIGHBORHOOD_RADII.includes(radius))throw Error('Choose a map tile and a supported neighborhood radius.');
 const result={center:{...center},radius,tiles:0,homes:0,residents:0,power:0,water:0,waste:0,...Object.fromEntries(fields.map(k=>[k,0]))},homes=new Set();
 for(let y=Math.max(0,center.y-radius);y<=Math.min(city.size-1,center.y+radius);y++)for(let x=Math.max(0,center.x-radius);x<=Math.min(city.size-1,center.x+radius);x++){
  if((x-center.x)**2+(y-center.y)**2>radius**2)continue;
  const t=city.tiles[y*city.size+x];result.tiles++;
  if(t.type!=='residential'||!t.level)continue;
  const people=occupancy(t.level)*8;result.residents+=people;homes.add(t.lotRoot??y*city.size+x);result.power+=t.powered?people:0;result.water+=t.watered?people:0;result.waste+=Math.max(0,t.waste||0);
  for(const k of fields)result[k]+=(t[k]||0)*people;
 }
 result.homes=homes.size;for(const k of fields)result[k]=result.residents?result[k]/result.residents:null;
 result.power=result.residents?result.power/result.residents*100:null;result.water=result.residents?result.water/result.residents*100:null;return result;
}
const metrics=[['power','Homes with electricity','power'],['water','Homes with water','water'],['policeCoverage','Police coverage','police'],['fireCoverage','Fire coverage','fire'],['healthCoverage','Healthcare access','health'],['childEducationCoverage','School access · ages 0–14','schoolAccess'],['collegeEducationCoverage','College access · ages 15–24','collegeAccess'],['adultEducationCoverage','Adult learning access · ages 25+','adultAccess'],['airPollution','Air pollution at homes','pollution'],['waterPollution','Water pollution at homes','waterPollution'],['crime','Crime at homes','crime'],['landValue','Land value at homes','landValue']];
const number=n=>n===null?'No residents':n.toLocaleString('en-US',{maximumFractionDigits:1});
export function showNeighborhoodReport(ui,center,radius=4){const d=neighborhoodSnapshot(ui.city(),center,radius);
 ui.dialog('Neighborhood services',`<p>Centered on tile ${center.x+1}, ${center.y+1}. Compare conditions around this location before placing or funding services.</p><label>Neighborhood radius <select id="neighborhoodRadius">${NEIGHBORHOOD_RADII.map(r=>`<option value="${r}" ${r===radius?'selected':''}>${r} tiles</option>`).join('')}</select></label><p>${d.tiles} tiles in a circular area · ${d.homes} occupied residential buildings intersect this area · ${number(d.residents)} residents in selected residential tiles.</p>${d.residents?'':'<p>No occupied homes in this area. Enlarge the radius or inspect another neighborhood to compare residential conditions.</p>'}<div class="table-scroll"><table><thead><tr><th>Condition</th><th>Local value</th><th>Map</th></tr></thead><tbody>${metrics.map(([key,label,layer])=>`<tr><td>${label}</td><td>${number(d[key])}${d[key]===null?'':fields.slice(6).includes(key)?' / 100':'%'}</td><td><button data-neighborhood-layer="${layer}">View ${label.toLowerCase()}</button></td></tr>`).join('')}<tr><td>Uncollected garbage at homes</td><td>${number(d.waste)} units</td><td><button data-neighborhood-layer="garbage">View garbage</button></td></tr></tbody></table></div><p>Percentages and scores are weighted by residents in the selected tiles. Buildings crossing the boundary contribute only their selected tiles. School, college and adult access describe available coverage, not a local age census. Utility percentages count residents on served tiles, not delivered utility units. Garbage is summed across selected occupied homes.</p><div class="actions"><button id="neighborhoodCivic">Plan civic services</button><button id="neighborhoodUtilities">Plan utilities</button><button id="neighborhoodBack">Back to tile</button></div>`);
 document.getElementById('neighborhoodRadius').onchange=e=>{showNeighborhoodReport(ui,center,Number(e.target.value));document.getElementById('neighborhoodRadius').focus();};document.querySelectorAll('[data-neighborhood-layer]').forEach(b=>b.onclick=()=>{ui.close();ui.center(center);ui.layer(b.dataset.neighborhoodLayer);});document.getElementById('neighborhoodCivic').onclick=ui.civic;document.getElementById('neighborhoodUtilities').onclick=ui.utilities;document.getElementById('neighborhoodBack').onclick=ui.back;
}
export function installNeighborhoodLink(ui,center){const button=document.createElement('button');button.id='inspectNeighborhood';button.textContent='Inspect neighborhood services';button.onclick=()=>showNeighborhoodReport(ui,center);document.getElementById('dialogBody').append(button);}
